<?php require_once __DIR__.'/../auth.php'; require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$row=['name'=>'','email'=>'','mobile'=>'','course'=>'BCA','year'=>1,'gender'=>'Prefer not to say'];$errors=[];
if($id){$s=$conn->prepare('SELECT name,email,mobile,course,year,gender FROM students WHERE student_id=?');$s->bind_param('i',$id);$s->execute();$found=$s->get_result()->fetch_assoc();$s->close();if(!$found){set_flash('Student not found.','error');redirect('index.php');}$row=$found;}
if($_SERVER['REQUEST_METHOD']==='POST'){$row=array_merge($row,['name'=>trim($_POST['name']??''),'email'=>strtolower(trim($_POST['email']??'')),'mobile'=>trim($_POST['mobile']??''),'course'=>trim($_POST['course']??''),'year'=>(int)($_POST['year']??0),'gender'=>trim($_POST['gender']??'')]);if(mb_strlen($row['name'])<2)$errors[]='Name is required.';if(!filter_var($row['email'],FILTER_VALIDATE_EMAIL))$errors[]='Valid email required.';if(!preg_match('/^[0-9]{10,15}$/',$row['mobile']))$errors[]='Mobile must be 10–15 digits.';if(!in_array($row['course'],['BCA','B.Tech','BBA','MCA'],true)||$row['year']<1||$row['year']>4)$errors[]='Select valid course and year.';if(!$errors){try{if($id){$s=$conn->prepare('UPDATE students SET name=?,email=?,mobile=?,course=?,year=?,gender=? WHERE student_id=?');$s->bind_param('ssssisi',$row['name'],$row['email'],$row['mobile'],$row['course'],$row['year'],$row['gender'],$id);}else{$hash=password_hash(bin2hex(random_bytes(24)),PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO students(name,email,mobile,password_hash,course,year,gender,role) VALUES(?,?,?,?,?,?,?,'student')");$s->bind_param('sssssis',$row['name'],$row['email'],$row['mobile'],$hash,$row['course'],$row['year'],$row['gender']);}$s->execute();$s->close();log_action($conn,(int)$_SESSION['student_id'],$id?'student_update':'student_create',$row['email']);set_flash('Student saved successfully.');redirect('index.php');}catch(mysqli_sql_exception $ex){$errors[]=$ex->getCode()===1062?'Email is already in use.':'Could not save student.';}}}
page_start($id?'Edit Student':'Add Student');if($errors){echo '<ul class="flash error">';foreach($errors as $er)echo '<li>'.e($er).'</li>';echo '</ul>';}
?>
<form method="post"><input type="hidden" name="id" value="<?=$id?>"><label>Name</label><input name="name" required value="<?=e($row['name'])?>"><label>Email</label><input type="email" name="email" required value="<?=e($row['email'])?>"><label>Mobile</label><input name="mobile" required pattern="[0-9]{10,15}" value="<?=e($row['mobile'])?>"><label>Course</label><select name="course"><?php foreach(['BCA','B.Tech','BBA','MCA'] as $c):?><option value="<?=e($c)?>" <?=$row['course']===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><label>Year</label><select name="year"><?php for($y=1;$y<=4;$y++):?><option value="<?=$y?>" <?=(int)$row['year']===$y?'selected':''?>>Year <?=$y?></option><?php endfor;?></select><label>Gender</label><select name="gender"><?php foreach(['Female','Male','Other','Prefer not to say'] as $g):?><option value="<?=e($g)?>" <?=$row['gender']===$g?'selected':''?>><?=e($g)?></option><?php endforeach;?></select><button type="submit">Save student</button></form><?php page_end(); ?>
